#!/usr/bin/env node
/**
 * Fails the build on any fact with no source.
 *
 * Every fact card shows "Source: <publisher>" (FactModal and ImageLightbox).
 * It stays out of the fact page's meta description, which is the share
 * preview text and needs every character for the fact. That line is a promise that the
 * publisher backs the card, so a fact without one cannot ship. Sources live in
 * src/lib/data/factSources.js, generated by scripts/generate-fact-sources.mjs
 * from the sourcing passes in docs/fact-sources/.
 *
 * A new fact needs a sourcing pass entry for its id, then a rerun of the
 * generator.
 *
 * Usage:  node scripts/check-fact-sources.mjs
 */
const { facts } = await import('../src/lib/data/facts.js');
const { FACT_SOURCES } = await import('../src/lib/data/factSources.js');

const missing = facts.filter((f) => !String(FACT_SOURCES[f.id] || '').trim()).map((f) => f.id);
const orphans = Object.keys(FACT_SOURCES).filter((id) => !facts.some((f) => String(f.id) === id));

if (missing.length) {
  console.error(`Fact sources: ${missing.length} fact(s) with no source: ${missing.join(', ')}`);
  console.error('\nRecord a source for each in docs/fact-sources/, then run node scripts/generate-fact-sources.mjs.');
  process.exit(1);
}
if (orphans.length) {
  console.log(`  note: sources kept for ids no longer in facts.js: ${orphans.join(', ')}`);
}
console.log(`Fact sources: all ${facts.length} facts have a source.`);
